pairs={'hairHead':('crown','chin'),'torso':('collar','hem'),'upperArm':('shoulder','elbow'),'forearm':('elbow','wrist'),'thigh':('hip','knee'),'shin':('knee','ankle'),'shoe':('heel','toe'),'shoulders':('shoulder','shoulderFar')}
