lines=['# Gojo round-5 final-atlas audit — Astra / medium','', 'Audited commit `941d8e08f85b79d47ffaae1774e14530613ad856`. Scope: idle v08 (8 frames), light3 v06 (7), airRecover v05 (3), directly extracted from the actual quantized atlas. This is a technical audit, not an approval. User approval of idle08 and its hands-down stance is preserved.','', '## Verdicts','']
